{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "female"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "code": {
          "text": "Faecal impaction with overflow incontinence (encopresis)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "code": {
          "text": "Chronic functional constipation"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Bowel movement frequency"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Opening bowels maybe 1–2 times per week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Stool characteristics and defecation symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Very large, hard stools that are painful to pass and sometimes block the toilet; increased stool holding for several months because it hurts when stool finally comes out and because the patient dislikes public toilets."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Faecal soiling"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Daily small-volume soiling in underwear over the last few weeks; described as skid marks and stool leaking out."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Abdominal symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Feels bloated and incompletely emptied, with dull lower abdominal discomfort."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Relevant reported negatives"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No rectal bleeding, melena, fever, nausea or vomiting, urinary symptoms, saddle anaesthesia, or leg weakness. Weight stable."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Bowel regimen adherence"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports not taking Movicol as prescribed and having run out weeks ago; says they forgot to get more."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Diet, fluid intake, and activity"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Lives alone, has low activity, a low-fibre diet, mainly drinks tea, and has limited water intake."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
          {
            "code": {
              "text": "Systolic blood pressure"
            },
            "valueQuantity": {
              "value": 138,
              "unit": "mmHg"
            }
          },
          {
            "code": {
              "text": "Diastolic blood pressure"
            },
            "valueQuantity": {
              "value": 82,
              "unit": "mmHg"
            }
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Heart rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 76,
          "unit": "beats/min"
        },
        "interpretation": [
          {
            "text": "Regular"
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Temperature status"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Afebrile."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Body mass index"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 26,
          "unit": "kg/m2"
        },
        "note": [
          {
            "text": "Approximate."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "General appearance and mobility"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Looks well and mobile, a bit anxious, with faint faecal odour."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Abdominal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Abdomen soft and mildly distended, with generalised fullness especially in the left lower quadrant and mild discomfort only; no peritonism or obvious mass."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Perianal and rectal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Perianal irritation and a small amount of soft stool externally. Good tone. Rectum loaded with a large amount of firm stool; no discrete mass, fissures, haemorrhoids, or fresh blood seen. Chaperone present."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Patient-reported previous colonoscopy result"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Colonoscopy reportedly normal approximately 8 years ago."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Perindopril"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "5 mg in the morning; often missed.",
            "timing": {
              "code": {
                "text": "Morning"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 5,
                  "unit": "mg"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Atorvastatin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "20 mg at night; takes it when remembered.",
            "timing": {
              "code": {
                "text": "At night"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 20,
                  "unit": "mg"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-3",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-3",
        "status": "unknown",
        "medicationCodeableConcept": {
          "text": "Macrogol 3350 with electrolytes (Movicol)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Patient reports currently taking none; ran out weeks ago and had not obtained more."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-4",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-4",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "As needed; dose and route not stated.",
            "asNeededBoolean": true
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Macrogol 3350 with electrolytes (Movicol) sachets"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Days 1–3: take 1 sachet hourly up to a maximum of 8 sachets per day; can space to every 2 hours if cramps or bloating. Aim for large stool output or clear liquid stools.",
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "h",
                "boundsDuration": {
                  "value": 3,
                  "unit": "days"
                }
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "sachet"
                }
              }
            ],
            "maxDosePerPeriod": {
              "numerator": {
                "value": 8,
                "unit": "sachets"
              },
              "denominator": {
                "value": 1,
                "unit": "day"
              }
            }
          },
          {
            "text": "Then take 1–2 sachets daily on an ongoing basis, titrating to keep stools soft at least every 1–2 days; do not stop once improved.",
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseRange": {
                  "low": {
                    "value": 1,
                    "unit": "sachet"
                  },
                  "high": {
                    "value": 2,
                    "unit": "sachets"
                  }
                }
              }
            ]
          }
        ],
        "note": [
          {
            "text": "PBS script printed for a quantity covering 3–5 days of intensive treatment plus at least 1 month of maintenance."
          }
        ]
      }
    }
  ]
}

